/* KORUK ASİSTAN — TEK MERKEZİ DESIGN SYSTEM
   Android / iOS / web aynı responsive çekirdeği kullanır. */
 /* ═══════════════════════════════════════════════════════════════════════════════
   KORUK ASİSTAN — TEMA MERKEZİ  (tek yetkili tanım)
   Uygulamadaki her renk / yüzey / metin / gölge / ölçü bu bloktan gelir.
   • 1) :root — iki temada ortak sabitler ve türev (var) tanımlar
   • 2) :root (açık palet) ve html[data-theme="dark"] (koyu palet) — yalnızca temaya göre
        değişen değerler; iki blok aynı sırada tutulur, yan yana okunabilir.
   Başka hiçbir yerde html düzeyinde değişken tanımlanmaz. Yeni renk gerekiyorsa buraya ekle.
   ═══════════════════════════════════════════════════════════════════════════════ */
:root{
  color-scheme:light;
  /* ── ÖLÇÜLER · TİPOGRAFİ · HAREKET ── */
  --ka-avatar-size:42px;
  --ka-profile-avatar-size:44px;
  --ka-profile-avatar-compact-size:34px;
  --ka-font:Inter,Manrope,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
  --ka-font-mono:"JetBrains Mono",Consolas,monospace;
  --ka-font-size-xs:var(--ka-fs-11);
  --ka-font-size-sm:var(--ka-fs-13);
  --ka-font-size-md:var(--ka-fs-15);
  --ka-font-size-lg:var(--ka-fs-18);
  --ka-font-size-xl:var(--ka-fs-22);
  --ka-font-size-2xl:var(--ka-fs-28);
  --ka-line-height:calc(1.5 * var(--ka-lh-k));
  --ka-space-1:var(--ka-sp-4);
  --ka-space-2:var(--ka-sp-8);
  --ka-space-3:var(--ka-sp-12);
  --ka-space-4:var(--ka-sp-16);
  --ka-space-5:var(--ka-sp-20);
  --ka-space-6:var(--ka-sp-24);
  --ka-space-8:var(--ka-sp-32);
  --ka-control-height-sm:36px;
  --ka-control-height:44px;
  --ka-control-height-lg:50px;
  --ka-header-height:64px;
  --ka-bottom-nav-height:72px;
  --ka-content-max-width:1180px;
  --ka-safe-top:env(safe-area-inset-top,0px);
  --ka-safe-right:env(safe-area-inset-right,0px);
  --ka-safe-bottom:env(safe-area-inset-bottom,0px);
  --ka-safe-left:env(safe-area-inset-left,0px);
  --ka-radius-sm:var(--ka-r-1);
  --ka-radius-md:var(--ka-r-3);
  --ka-radius-lg:var(--ka-r-6);
  --ka-radius-xl:var(--ka-r-8);
  --ka-radius-pill:999px;
  --ka-transition-fast:var(--ka-dur-120) ease;
  --ka-transition:var(--ka-dur-180) ease;

  /* ── KÖŞE ÖLÇEĞİ — tüm köşeler tek değerden türer: --ka-radius-base (0 = köşeli, 20 = çok yuvarlak) ── */
  --ka-radius-base:14px;
  --ka-r-1:max(0px,calc(var(--ka-radius-base) - 6px));    /* 8  */
  --ka-r-2:max(0px,calc(var(--ka-radius-base) - 4px));    /* 10 */
  --ka-r-3:max(0px,calc(var(--ka-radius-base) - 2px));    /* 12 */
  --ka-r-4:var(--ka-radius-base);                          /* 14 */
  --ka-r-5:calc(var(--ka-radius-base) + 2px);              /* 16 */
  --ka-r-6:calc(var(--ka-radius-base) + 4px);              /* 18 */
  --ka-r-7:calc(var(--ka-radius-base) + 6px);              /* 20 */
  --ka-r-8:calc(var(--ka-radius-base) + 8px);              /* 22 */
  --ka-r-9:calc(var(--ka-radius-base) + 10px);             /* 24 */
  --ka-r-10:calc(var(--ka-radius-base) + 14px);            /* 28 */

  /* ── ÇİZGİ · HALKA · BULANIKLIK ── */
  --ka-border-w:1px;                     /* tüm kart/kutu/buton çizgi kalınlığı */
  --ka-ring-w:3px;                       /* odak halkası kalınlığı */
  --ka-ring-offset:2px;                    /* odak halkasının nesneden uzaklığı */
  --ka-blur-k:1;                         /* bulanıklık çarpanı (1 = olduğu gibi, 0 = bulanıklık yok, 1.5 = daha buzlu) */

  /* ── BUTON — tüm .ka-btn çeşitleri ve düğme benzeri öğeler ── */
  --ka-btn-radius:var(--ka-r-3);         /* orta düğme köşesi */
  --ka-btn-radius-sm:var(--ka-r-2);      /* küçük düğme köşesi */
  --ka-btn-radius-lg:var(--ka-r-5);      /* büyük düğme köşesi */
  --ka-btn-grow:0px;                     /* tüm düğme yüksekliklerine eklenir (+4px = daha iri, -4px = sıkışık) */
  --ka-btn-h-sm:calc(var(--ka-control-height-sm) + var(--ka-btn-grow));
  --ka-btn-h-md:calc(var(--ka-control-height) + var(--ka-btn-grow));
  --ka-btn-h-lg:calc(var(--ka-control-height-lg) + var(--ka-btn-grow));
  --ka-btn-px:var(--ka-space-4);         /* yatay iç boşluk (orta) */
  --ka-btn-px-sm:var(--ka-space-3);
  --ka-btn-px-lg:var(--ka-space-5);
  --ka-btn-gap:var(--ka-space-2);        /* ikon ile yazı arası */
  --ka-btn-weight:750;
  --ka-btn-tracking:-.01em;
  --ka-btn-border-w:var(--ka-border-w);
  --ka-btn-danger-bg:var(--ka-danger);
  --ka-btn-danger-text:var(--ka-danger-text);
  --ka-btn-ghost-bg:transparent;
  --ka-btn-ghost-hover:var(--ka-muted-bg);
  --ka-btn-ghost-text:var(--ka-text);

  /* ── FORM KUTUSU — input / select / textarea / .ka-input ── */
  --ka-field-radius:var(--ka-r-4);
  --ka-field-radius-sm:var(--ka-r-2);
  --ka-field-grow:0px;                   /* tüm form kutusu yüksekliklerine eklenir */
  --ka-field-h-md:calc(var(--ka-control-height) + var(--ka-field-grow));
  --ka-field-px:var(--ka-sp-12);
  --ka-field-py:var(--ka-sp-9);
  --ka-field-border-w:var(--ka-border-w);
  --ka-field-textarea-h:96px;
  --ka-field-ring:0 0 0 var(--ka-ring-w) var(--ka-focus);   /* odaktaki halka */

  /* ── KART ── */
  --ka-card-radius:var(--ka-r-6);        /* standart kart */
  --ka-card-radius-sm:var(--ka-r-4);     /* iç kutu / satır kartı */
  --ka-card-radius-lg:var(--ka-r-7);     /* büyük kart */
  --ka-card-pad:var(--ka-space-4);
  --ka-card-border-w:var(--ka-border-w);

  /* ── KAPAK (hero / sayfa başlığı kartları) ── */
  --ka-cover-radius:var(--ka-r-8);
  --ka-cover-radius-sm:var(--ka-r-6);
  --ka-cover-radius-lg:var(--ka-r-10);

  /* ── SAYFA BAŞLIĞI — her sayfanın geri düğmesinin altındaki başlık kartı (hepsi bu değerlerle çizilir) ── */
  --ka-ph-bg:radial-gradient(120% 100% at 100% 0%,rgba(var(--t-accent-rgb),.11),transparent 58%),var(--ka-card-bg);  /* kart zemini; düz başlık için: transparent */
  --ka-ph-border-w:var(--ka-border-w);   /* çerçeve kalınlığı (0 = çerçevesiz) */
  --ka-ph-border:var(--gl-edge);         /* çerçeve rengi */
  --ka-ph-radius:var(--ka-cover-radius); /* köşe */
  --ka-ph-shadow:var(--gl-shadow);       /* gölge (none = düz) */
  --ka-ph-blur:var(--gl-blur);           /* cam bulanıklığı */
  --ka-ph-pad-y:var(--ka-sp-14);         /* iç boşluk: üst-alt */
  --ka-ph-pad-x:var(--ka-sp-16);         /* iç boşluk: sağ-sol */
  --ka-ph-gap:var(--ka-sp-12);           /* başlık ile eylem/rozet arası */
  --ka-ph-min-h:0px;                     /* en az yükseklik (ör. 120px = daha kapak gibi) */
  --ka-ph-bar-pad-y:var(--ka-sp-6);       /* çubuk başlık (detay sayfası üst çubuğu): iç boşluk üst-alt */
  --ka-ph-bar-pad-x:var(--ka-sp-8);       /* çubuk başlık: iç boşluk sağ-sol */
  --ka-ph-bar-title-size:var(--ka-fs-17); /* çubuk başlık yazı boyutu */
  --ka-ph-title:var(--gl-fg);            /* başlık rengi */
  --ka-ph-title-size:var(--ka-fs-22);
  --ka-ph-title-weight:var(--ka-fw-800);
  --ka-ph-title-tracking:var(--ka-ls-n02);
  --ka-ph-title-lh:var(--ka-lh-1-2);
  --ka-ph-sub:var(--gl-sub);             /* açıklama rengi */
  --ka-ph-sub-size:var(--ka-fs-13);
  --ka-ph-sub-lh:var(--ka-lh-1-35);
  --ka-ph-kicker:var(--hd-chip);         /* başlık üstü küçük etiket (ör. ÖĞRENCİ MERKEZİ) */
  --ka-ph-kicker-size:var(--ka-fs-10);
  --ka-ph-kicker-tracking:var(--ka-ls-12);
  --ka-ph-icon-bg:linear-gradient(135deg,rgba(var(--t-gold-hi-rgb),.30),rgba(var(--t-gold-lo-rgb),.12));  /* başlık ikon kutusu */
  --ka-ph-icon-fg:var(--hd-chip);
  --ka-ph-icon-border:rgba(var(--t-accent-rgb),.34);
  --ka-ph-icon-radius:var(--ka-cover-radius-sm);
  --ka-ph-icon-shadow:0 var(--ka-sh-6) var(--ka-sh-18) rgba(var(--t-gold-lo-rgb),calc(.14 * var(--ka-shadow-a)));
  --ka-ph-icon-size:46px;                /* genel .ka-page-head__icon kutusunun boyutu */
  --ka-ph-deco:none;                     /* sayfaların kendi süs şekilleri/emojileri: none = kapalı, block = açık */

  /* ── PENCERE · ALT SAYFA · AÇILIR MENÜ ── */
  --ka-sheet-radius:var(--ka-r-6);       /* ortadaki pencere */
  --ka-sheet-radius-lg:var(--ka-r-9);    /* alttan açılan sayfa / büyük pencere */
  --ka-sheet-pad:var(--ka-space-4);

  /* ── YAPIŞKAN ŞERİTLER — kaydırırken içeriğin üstünde kalan şerit / başlık / tablo sütunu. Saydam olursa alttan kayan yazılar üst üste biner; bu yüzden hepsi bu opak zemini kullanır ── */
  --ka-sticky-bg:var(--pp-solid);                 /* opak zemin (şeritler) */
  --ka-sticky-cell-bg:color-mix(in srgb,var(--gl-fg) 6%,var(--ka-sticky-bg));  /* opak, hafif tonlu zemin (yapışkan tablo başlığı / ilk sütun / sekme şeridi) */

  /* ── PENCERE BAŞLIĞI — her pencere / alt sayfa / menünün üst şeridi (başlık + kapat düğmesi) ── */
  --ka-sheet-head-bg:transparent;                 /* şerit zemini */
  --ka-sheet-head-stuck-bg:var(--ka-sticky-bg);   /* içerik altından kayan (yapışkan) şeridin zemini */
  --ka-sheet-head-border-w:var(--ka-border-w);    /* alt çizgi kalınlığı (0 = çizgisiz) */
  --ka-sheet-head-border:var(--gl-sep);           /* alt çizgi rengi */
  --ka-sheet-head-pad-y:var(--ka-sheet-pad);      /* iç boşluk: üst-alt */
  --ka-sheet-head-pad-x:var(--ka-sheet-pad);      /* iç boşluk: sağ-sol */
  --ka-sheet-head-gap:var(--ka-sp-10);            /* başlık ile kapat düğmesi arası */
  --ka-sheet-head-title:var(--gl-fg);             /* başlık rengi */
  --ka-sheet-head-title-size:var(--ka-fs-18);
  --ka-sheet-head-title-weight:var(--ka-fw-800);
  --ka-sheet-head-title-lh:var(--ka-lh-1-2);
  --ka-sheet-head-sub:var(--gl-sub);              /* açıklama rengi */
  --ka-sheet-head-sub-size:var(--ka-fs-12);
  --ka-sheet-head-kicker:var(--hd-chip);          /* başlık üstü küçük etiket (ör. YENİ DUYURU) */
  --ka-sheet-head-kicker-size:var(--ka-fs-10);
  --ka-sheet-close-size:calc(44px + var(--ka-btn-grow));  /* kapat (×) düğmesi */
  --ka-sheet-close-bg:var(--gl-field);
  --ka-sheet-close-fg:var(--gl-fg);
  --ka-sheet-close-border:var(--gl-edge);
  --ka-sheet-close-radius:var(--ka-btn-radius-lg);

  /* ── ROZET · ETİKET ── */
  --ka-chip-radius:var(--ka-radius-pill);
  --ka-chip-radius-sm:var(--ka-r-2);
  --ka-chip-h:24px;
  --ka-chip-px:var(--ka-sp-8);
  --ka-chip-weight:750;

  /* ── SEKME ── */
  --ka-tab-radius:var(--ka-radius-pill);
  --ka-tab-h:var(--ka-control-height-sm);
  --ka-tab-px:var(--ka-space-3);
  --ka-tab-weight:750;

  /* ── KOMUT / ARAMA KUTUSU ── */
  --ka-cmd-radius:var(--ka-r-6);
  --ka-cmd-border-w:var(--ka-border-w);
  --ka-cmd-h:54px;
  --ka-cmd-h-sm:52px;                    /* dar ekran */
  --ka-cmd-bg:var(--ka-input-bg);
  --ka-cmd-border:var(--ka-input-border);
  --ka-cmd-shadow:var(--ka-shadow-sm);
  --ka-cmd-icon:var(--ka-primary);

  /* ── ARKA PLAN (koyu temada sabit renkli ışık küreleri) ── */
  --ka-orb-a:rgba(var(--c-indigo),.30);   /* sol üst */
  --ka-orb-b:rgba(var(--c-emerald),.24);  /* sağ alt */
  --ka-orb-c:rgba(var(--c-amber),.16);    /* sağ orta */
  --ka-orb-blur:80px;

  /* ── TABLO ── */
  --ka-table-radius:var(--ka-radius-md);
  --ka-table-cell-py:var(--ka-sp-10);
  --ka-table-cell-px:var(--ka-sp-12);

  /* ── MARKA PALETİ — rengi değiştirmek için bu bölüm ── */
  --t-accent-rgb:255,196,0;              /* marka sarısı (RGB üçlüsü: şeffaf türevler rgba(var(--t-accent-rgb),.x)) */
  --t-accent:rgb(var(--t-accent-rgb));
  --t-accent-deep:#e5b000;               /* hover / gradyan sonu (açık temada) */
  --t-accent-bright:#ffd34d;             /* hover (koyu temada) · koyu zeminde vurgulu metin */
  --t-on-accent:#111;                    /* sarı yüzeyin üstündeki yazı / ikon */

  --t-gold-hi-rgb:255,216,77;            /* sarı butonların üst gradyan ucu */
  --t-gold-lo-rgb:255,184,0;             /* sarı butonların alt gradyan ucu */
  --t-gold-hover-hi-rgb:255,224,102;     /* sarı butonların üzerine gelince: üst gradyan ucu */
  --t-gold-hover-lo-rgb:255,194,26;      /* sarı butonların üzerine gelince: alt gradyan ucu */
  --t-on-accent-ink:#1a1300;             /* gradyanlı sarı yüzeyin üstündeki koyu yazı */
  --t-accent-dim:#c99700;                /* koyu sarı: canlı ilerleme çubuğu, ders çizelgesi vurgusu */

  /* ── KATEGORİ PALETİ — ana sayfa bölümleri, menü grupları, rozetler (RGB üçlüsü) ── */
  --c-amber:245,158,11;
  --c-emerald:16,185,129;
  --c-indigo:99,102,241;
  --c-red:239,68,68;
  --c-blue:59,130,246;
  --c-rose:244,63,94;
  --c-mint:52,211,153;
  --c-violet:139,92,246;
  --c-yellow:234,179,8;
  --c-orange:249,115,22;
  --c-cyan:6,182,212;
  --c-slate:148,163,184;
  --c-sky:14,165,233;
  --c-lemon:250,204,21;
  --c-teal:20,184,166;
  --c-pink:236,72,153;
  --c-fuchsia:217,70,239;
  --c-lime:132,204,22;
  --c-green:34,197,94;
  --c-periwinkle:129,140,248;
  --c-coral:251,80,100;
  --c-orchid:192,132,252;
  --c-azure:56,189,248;

  /* ── MARKA · VURGU (türevler) ── */
  --ka-primary:var(--t-accent);
  --ka-primary-hover:var(--t-accent-deep);
  --ka-on-accent:#fff;
  --ka-on-accent-muted:rgba(255,255,255,.84);
  --ka-on-accent-soft:rgba(255,255,255,.14);
  --ka-on-accent-border:rgba(255,255,255,.28);
  --ka-on-accent-avatar:rgba(255,255,255,.16);
  --ka-on-accent-glow:rgba(255,255,255,.07);
  --ka-accent:#35d07f;
  --ka-nav-menu-start:var(--t-accent);
  --ka-nav-menu-end:var(--t-accent-deep);
  --ka-button-bg:var(--t-accent);
  --ka-button-text:var(--t-on-accent);
  --ka-input-focus:var(--t-accent);
  --ka-focus:rgba(var(--t-accent-rgb),.28);
  --ka-live-progress:linear-gradient(90deg,var(--t-accent),var(--t-accent-dim));

  /* ── ZEMİN · METİN · ÇERÇEVE ── */
  --ka-surface-1:var(--ka-card-raised-bg);
  --ka-surface-2:var(--ka-muted-bg);
  --ka-page-surface:var(--ka-app-bg);
  --ka-surface-raised:var(--ka-card-raised-bg);
  --ka-surface-muted:var(--ka-muted-bg);
  --ka-content-text:var(--ka-text);
  --ka-content-muted:var(--ka-text-muted);
  --ka-content-border:var(--ka-border);
  --ka-bg:var(--ka-app-bg);

  /* ── KABUK — ÜST BAŞLIK · ALT NAVİGASYON · AÇILIR PENCERE ── */
  --ka-nav-shadow:var(--ka-shadow-md);
  --ka-notification-badge-bg:var(--ka-danger);
  --ka-notification-badge-text:var(--ka-danger-text);
  --ka-notification-badge-border:var(--ka-header-bg);
  --ka-shadow-sm:0 var(--ka-sh-4) var(--ka-sh-14) rgba(var(--ka-shadow-rgb),calc(.07 * var(--ka-shadow-a)));
  --ka-status-bg:rgba(255,255,255,.06);
  --ka-header-text:var(--ka-text);
  --ka-nav-menu-icon:var(--ka-text);

  /* ── BUTON · FORM ALANI ── */
  --ka-button-secondary-text:var(--ka-text);
  --ka-input-text:var(--ka-text);

  /* ── DURUM · CİNSİYET ── */
  --ka-gender-girl:#cf4a67;
  --ka-gender-boy:#6357d6;
  --ka-success:#22bf73;
  --ka-warning:#b76500;
  --ka-danger:#ef4b5f;
  --ka-danger-text:#fff;
  --ka-info:#3b91e8;
  --ka-student-boy:var(--ka-info);
  --ka-student-girl:var(--ka-module-communication-1);

  /* ── MODÜL AİLELERİ ── */
  --ka-detail-surface:var(--ka-card-bg);
  --ka-detail-accent:var(--ka-primary);
  --ka-detail-hero-start:var(--ka-primary);
  --ka-detail-hero-deep:#765600;
  --ka-detail-hero-text:#111;
  --ka-detail-hero-muted:#2b250f;
  --ka-detail-hero-glow:var(--ka-on-accent-glow);
  --ka-avatar-bg:var(--ka-primary-soft);
  --ka-avatar-text:var(--ka-primary);
  --ka-food-mon-bg:var(--ka-card-raised-bg);
  --ka-food-mon-border:var(--ka-border);
  --ka-food-mon-text:var(--ka-text);
  --ka-food-tue-bg:var(--ka-card-raised-bg);
  --ka-food-tue-border:var(--ka-border);
  --ka-food-tue-text:var(--ka-text);
  --ka-food-wed-bg:var(--ka-card-raised-bg);
  --ka-food-wed-border:var(--ka-border);
  --ka-food-wed-text:var(--ka-text);
  --ka-food-thu-bg:var(--ka-card-raised-bg);
  --ka-food-thu-border:var(--ka-border);
  --ka-food-thu-text:var(--ka-text);
  --ka-food-fri-bg:var(--ka-card-raised-bg);
  --ka-food-fri-border:var(--ka-border);
  --ka-food-fri-text:var(--ka-text);
  --ka-module-people-1:var(--ka-primary);
  --ka-module-people-2:var(--ka-primary-hover);
  --ka-module-exams-1:var(--ka-primary);
  --ka-module-exams-2:var(--ka-primary-hover);
  --ka-module-programs-1:var(--ka-primary);
  --ka-module-programs-2:var(--ka-primary-hover);
  --ka-module-communication-1:var(--ka-primary);
  --ka-module-communication-2:var(--ka-primary-hover);
  --ka-module-calendar-1:var(--ka-primary);
  --ka-module-calendar-2:var(--ka-primary-hover);
  --ka-module-transport-1:var(--ka-primary);
  --ka-module-transport-2:var(--ka-primary-hover);
  --ka-module-documents-1:var(--ka-primary);
  --ka-module-documents-2:var(--ka-primary-hover);
  --ka-module-management-1:var(--ka-primary);
  --ka-module-management-2:var(--ka-primary-hover);
  --ka-module-settings-1:var(--ka-primary);
  --ka-module-settings-2:var(--ka-primary-hover);
  --ka-detail-icon-surface:var(--ka-icon-surface);
  --ka-detail-icon-text:var(--ka-icon-text);
  --ka-detail-icon-border:var(--ka-icon-border);
  --ka-reminder-upcoming-bg:var(--ka-primary-soft);
  --ka-reminder-upcoming-text:var(--ka-primary);
  --ka-module-surface-raised:var(--ka-card-raised-bg);
